import { Canvas } from "@react-three/fiber";
import React from "react";
import { useMemo, useEffect, useState } from "react";
import {
  SphereGeometry,
  EdgesGeometry,
  Color,
  ShaderMaterial,
  Euler,
} from "three";

export default function WireframeSphere({
  radius = 5,
  segments = 32,
  startColor = 0x000099,
  endColor = 0x990000,
  rotationSpeed = 0.0005,
}) {
  const vertexShader = String.raw`
  uniform float rotationY;
  uniform vec3 startColor;
  uniform vec3 endColor;

  varying vec3 vColor;

  void main() {
    // Normalize position to unit sphere coordinates
    vec3 normalizedPosition = normalize(position);
    
    // Calculate spherical angles (theta and phi)
    float theta = atan(normalizedPosition.z, normalizedPosition.x);
    float phi = acos(normalizedPosition.y);
    float PI = 3.14;
    
    // Normalize angles to range between 0 and 1
    float normalizedTheta = theta / (PI);
    float normalizedPhi = (phi) / PI;
    
    // Use angles to determine color based on a wrapping pattern (e.g., sine wave)
    float colorFactor = sin(((normalizedPhi * PI)+rotationY) * 5.0);  // Adjust pattern as needed
    vColor = mix(startColor, endColor, colorFactor);
    
    vec4 mvPosition = modelViewMatrix * vec4(position, 1.0);
    gl_Position = projectionMatrix * mvPosition;
  }
`;

  const fragmentShader = String.raw`
  varying vec3 vColor;

  void main() {
    gl_FragColor = vec4(vColor, 1.0); // Set fragment color to interpolated color
  }
`;

  const [rotation, setRotation] = useState({ x: 0, y: 0 });

  const geometry = useMemo(() => {
    const sphereGeo = new SphereGeometry(radius, segments, segments);
    sphereGeo.computeVertexNormals(); // Needed for backface culling
    return sphereGeo;
  }, [radius, segments]);

  const wireframe = useMemo(() => {
    return new EdgesGeometry(geometry);
  }, [geometry]);

  const wireShaderMaterial = useMemo(() => {
    return new ShaderMaterial({
      vertexShader,
      fragmentShader,
      uniforms: {
        rotationY: { value: 0.0 },
        startColor: { value: new Color(startColor) },
        endColor: { value: new Color(endColor) },
      },
    });
  }, [vertexShader, fragmentShader, startColor, endColor]);

  useEffect(() => {
    const prefersReducedMotion = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    );

    const handleRotation = () => {
      if (!prefersReducedMotion.matches) {
        setRotation((prevRotation) => ({
          x: 0,
          y: prevRotation.y + rotationSpeed,
        }));
        wireShaderMaterial.uniforms.rotationY.value = rotation.y * 2.0;
      }
    };

    const intervalId = setInterval(handleRotation, 16); // Update rotation every 16ms (adjustable)

    return () => clearInterval(intervalId); // Cleanup on unmount
  }, [rotation, rotationSpeed, wireShaderMaterial.uniforms.rotationY]);

  return (
    <Canvas
      style={{
        position: "absolute",
        top: 0,
        left: 0,
        width: "100%",
        height: "100%",
        zIndex: -1,
      }}
    >
      <mesh rotation={new Euler(rotation.x, rotation.y)}>
        <lineSegments geometry={wireframe} material={wireShaderMaterial} />
      </mesh>
    </Canvas>
  );
}
