export function login(config: FieldValues) {
  return new Promise<KeyedObject>((res, rej) => {
    fetch("/users/login", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
      },
      body: JSON.stringify(config),
    })
      .then((response) => response.json())
      .then((data) => {
        res(data);
      })
      .catch((e) => {
        rej(e);
      });
  });
}

